typedef struct { _Atomic unsigned long ref; size_t len; char data[]; } body_t;
static _Atomic(body_t *) published;        /* snapshot pointer */
static mtx_t write_lock;                   /* serialises writers */

body_t *snapshot(void) { return atomic_load(&published); }   /* lock-free read */
void replace_from_template(const body_t *tmpl) {
    body_t *next = body_dup(tmpl);         /* copy-on-write step */
    mtx_lock(&write_lock);
    atomic_store(&published, next);        /* publish; readers keep the old body */
    mtx_unlock(&write_lock);
}
/* release: if (atomic_fetch_sub(&b->ref, 1) == 1) free(b); */
